// The existing single-edit API works. Preserve it while extending this module.
import {readFileSync} from 'node:fs';
import {pathToFileURL} from 'node:url';
function checkEdit(source,edit){
  if(typeof source!=='string'||edit===null||typeof edit!=='object'||Array.isArray(edit)
    ||!Number.isSafeInteger(edit.start)||!Number.isSafeInteger(edit.end)
    ||edit.start<0||edit.start>edit.end||edit.end>source.length
    ||typeof edit.before!=='string'||typeof edit.after!=='string')throw Error('invalid edit');
  if(source.slice(edit.start,edit.end)!==edit.before)throw Error('preimage mismatch');
}
export function applyEdit(source,edit){
  checkEdit(source,edit);
  return source.slice(0,edit.start)+edit.after+source.slice(edit.end);
}
// Every edit is validated against the original source and uses
// original-source coordinates. Conflicting edits are rejected before any
// output is produced; input arrays and objects are never mutated.
export function applyTransaction(source,edits){
  if(typeof source!=='string')throw Error('source must be a string');
  if(!Array.isArray(edits))throw Error('edits must be an array');
  for(const edit of edits)checkEdit(source,edit);
  for(let i=0;i<edits.length;i++){
    const a=edits[i];
    for(let j=i+1;j<edits.length;j++){
      const b=edits[j];
      const aInsertion=a.start===a.end,bInsertion=b.start===b.end;
      if(aInsertion&&bInsertion){
        if(a.start===b.start)throw Error('conflicting insertions');
      }else if(aInsertion){
        if(b.start<=a.start&&a.start<=b.end)throw Error('insertion conflicts with range');
      }else if(bInsertion){
        if(a.start<=b.start&&b.start<=a.end)throw Error('insertion conflicts with range');
      }else if(a.start<b.end&&b.start<a.end){
        throw Error('overlapping ranges');
      }
    }
  }
  let text='';
  let cursor=0;
  for(const edit of edits.slice().sort((x,y)=>x.start-y.start)){
    text+=source.slice(cursor,edit.start)+edit.after;
    cursor=edit.end;
  }
  text+=source.slice(cursor);
  return {text,applied:edits.length};
}
// JSON-file CLI: node patch-transaction.js INPUT_JSON_FILE
// Success prints one result JSON line and exits 0 with no stderr.
// Any failure (bad argument count, unreadable file, invalid JSON,
// invalid transaction) exits 2 with nonempty stderr and no stdout.
function cliFail(message){
  process.stderr.write(String(message)+'\n');
  process.exitCode=2;
}
function runCli(){
  if(process.argv.length!==3){
    cliFail('usage: node patch-transaction.js INPUT_JSON_FILE');
    return;
  }
  let raw;
  try{
    raw=readFileSync(process.argv[2],'utf8');
  }catch(error){
    cliFail('unreadable input file: '+error.message);
    return;
  }
  let data;
  try{
    data=JSON.parse(raw);
  }catch(error){
    cliFail('invalid JSON: '+error.message);
    return;
  }
  if(data===null||typeof data!=='object'||Array.isArray(data)){
    cliFail('input must be a JSON object with "source" and "edits"');
    return;
  }
  let result;
  try{
    result=applyTransaction(data.source,data.edits);
  }catch(error){
    cliFail('invalid transaction: '+error.message);
    return;
  }
  process.stdout.write(JSON.stringify(result)+'\n');
}
// Add the JSON-file CLI described by the work order without import side effects.
try{
  if(process.argv[1]!==undefined&&pathToFileURL(process.argv[1]).href===import.meta.url)runCli();
}catch(error){
  if(process.argv[1]!==undefined)cliFail('invalid entry point: '+error.message);
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {applyEdit,applyTransaction} from '../patch-transaction.js';
import {execFile} from 'node:child_process';
import {promisify} from 'node:util';
import {mkdtempSync,rmSync,writeFileSync,unlinkSync,existsSync} from 'node:fs';
import {tmpdir} from 'node:os';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
const edit=(start,end,before,after)=>({start,end,before,after});
const cli=path.join(path.dirname(fileURLToPath(import.meta.url)),'..','patch-transaction.js');
const execCli=promisify(execFile);
test('applyTransaction validates arguments without coercion',()=>{
  assert.throws(()=>applyTransaction(123,[edit(0,0,'','x')]),Error);
  assert.throws(()=>applyTransaction(null,[]),Error);
  assert.throws(()=>applyTransaction('abc',null),Error);
  assert.throws(()=>applyTransaction('abc','nope'),Error);
  assert.throws(()=>applyTransaction('abc',edit(0,1,'a','x')),Error);
  assert.throws(()=>applyTransaction('abc',[null]),Error);
  assert.throws(()=>applyTransaction('abc',[[]]),Error);
  assert.throws(()=>applyTransaction('abc',['x']),Error);
  assert.throws(()=>applyTransaction('abc',[42]),Error);
  assert.throws(()=>applyTransaction('abc',[edit('1',2,'b','X')]),Error);
  assert.throws(()=>applyTransaction('abc',[edit(1,'2','b','X')]),Error);
  assert.throws(()=>applyTransaction('abc',[edit(1.5,2,'b','X')]),Error);
  assert.throws(()=>applyTransaction('abc',[edit(-1,0,'','X')]),Error);
  assert.throws(()=>applyTransaction('abc',[edit(1,4,'bc','X')]),Error);
  assert.throws(()=>applyTransaction('abc',[edit(2,1,'b','X')]),Error);
  assert.throws(()=>applyTransaction('abc',[edit(1,2,null,'X')]),Error);
  assert.throws(()=>applyTransaction('abc',[edit(1,2,'b',7)]),Error);
  assert.throws(()=>applyTransaction('abc',[edit(1,2,'wrong','X')]),Error);
  assert.throws(()=>applyTransaction('abc',[edit(NaN,NaN,'','X')]),Error);
  assert.throws(()=>applyTransaction('abc',[edit(Infinity,Infinity,'','X')]),Error);
});
test('unknown fields are ignored and no-ops count',()=>{
  assert.deepEqual(applyTransaction('abc',[{start:1,end:2,before:'b',after:'b',extra:true}]),
    {text:'abc',applied:1});
  assert.deepEqual(applyTransaction('abc',[edit(1,2,'b','B'),{start:2,end:3,before:'c',after:'C',tag:0}]),
    {text:'aBC',applied:2});
});
test('adjacent ranges allowed; overlapping ranges rejected',()=>{
  assert.deepEqual(applyTransaction('abcd',[edit(0,2,'ab','x'),edit(2,4,'cd','y')]),{text:'xy',applied:2});
  assert.throws(()=>applyTransaction('abcdef',[edit(0,3,'abc','X'),edit(2,5,'cde','Y')]),Error);
  assert.throws(()=>applyTransaction('abcdef',[edit(0,3,'abc','X'),edit(1,2,'b','Y')]),Error);
  assert.throws(()=>applyTransaction('abcdef',[edit(0,3,'abc','X'),edit(3,5,'de','Y'),edit(4,6,'ef','Z')]),Error);
});
test('insertion conflict rules',()=>{
  // Distinct positions outside edited ranges are fine.
  assert.deepEqual(applyTransaction('abcdef',[edit(0,0,'','A'),edit(3,3,'','B'),edit(6,6,'','C')]),
    {text:'AabcBdefC',applied:3});
  // Two insertions at the same position conflict, even if one inserts ''.
  assert.throws(()=>applyTransaction('abc',[edit(1,1,'','x'),edit(1,1,'','y')]),Error);
  assert.throws(()=>applyTransaction('abc',[edit(1,1,'','x'),edit(1,1,'','')]),Error);
  // Insertion at either endpoint of a range conflicts.
  assert.throws(()=>applyTransaction('abcd',[edit(0,2,'ab','X'),edit(0,0,'','y')]),Error);
  assert.throws(()=>applyTransaction('abcd',[edit(0,2,'ab','X'),edit(2,2,'','y')]),Error);
  assert.throws(()=>applyTransaction('abcd',[edit(1,1,'','y'),edit(0,2,'ab','X')]),Error);
  // Just outside the range is allowed.
  assert.deepEqual(applyTransaction('abcd',[edit(1,3,'bc','X'),edit(3,3,'','y')]),{text:'aXyd',applied:2});
  assert.deepEqual(applyTransaction('abcd',[edit(0,1,'','y'),edit(0,1,'a','X')]),{text:'yXdcd',applied:2});
});
test('result is order independent and inputs are not mutated',()=>{
  const source='abcdef';
  const edits=[edit(3,5,'de','X'),edit(0,1,'a','LONG'),edit(5,5,'','!')];
  const snapshot=JSON.parse(JSON.stringify({source,edits}));
  const first=applyTransaction(source,edits);
  const reversed=applyTransaction(source,[...edits].reverse());
  assert.deepEqual(first,{text:'LONGbcXf!',applied:3});
  assert.deepEqual(first,reversed);
  assert.deepEqual({source,edits},snapshot);
});
test('code units, CR/LF and final newline are preserved',()=>{
  assert.deepEqual(applyTransaction('a\r\nb\tc\n',[edit(0,1,'a','Z')]),
    {text:'Z\r\nb\tc\n',applied:1});
  const emoji='a\ud83d\ude00c'; // UTF-16 length 4
  assert.deepEqual(applyTransaction(emoji,[edit(2,3,'\ud83d','X')]),{text:'aX\ude00c',applied:1});
  assert.deepEqual(applyTransaction(emoji,[edit(3,4,'\ude00','')]),{text:'a\ud83dc',applied:1});
  assert.deepEqual(applyTransaction('\n',[edit(0,1,'\n','')]),{text:'',applied:1});
});
test('empty transaction and empty source rules',()=>{
  assert.deepEqual(applyTransaction('tail\r\n',[]),{text:'tail\r\n',applied:0});
  assert.deepEqual(applyTransaction('',[edit(0,0,'','new')]),{text:'new',applied:1});
  assert.throws(()=>applyTransaction('',[edit(1,1,'','x')]),Error);
  assert.throws(()=>applyTransaction('',[edit(0,0,'','x'),edit(0,0,'','y')]),Error);
  assert.throws(()=>applyTransaction('abc',[]),Error); // still requires source string check path
  assert.deepEqual(applyTransaction('',[]),{text:'',applied:0});
});
test('importing the module does not run the CLI',async()=>{
  const {stdout,stderr,code}=await execCli(process.execPath,['-e',
    `import(${JSON.stringify(`'${cli}'`.replace(/^/,'file:///))});console.log('imported');`]);
  assert.equal(code,0);
  assert.equal(stdout,'imported\n');
  assert.equal(stderr,'');
});
test('CLI behaviors',async t=>{
  const dir=mkdtempSync(path.join(tmpdir(),'patch-transaction-'));
  t.after(()=>rmSync(dir,{recursive:true,force:true}));
  const write=(name,value)=>{
    const file=path.join(dir,name);
    writeFileSync(file,value,'utf8');
    return file;
  };
  const run=(args)=>execCli(process.execPath,[cli,...args],{encoding:'utf8'})
    .then(r=>({code:0,...r}),e=>({code:e.code ?? 1,stdout:e.stdout??'',stderr:e.stderr??''}));
  // Success: one result JSON line + newline, exit 0, no stderr.
  {
    const file=write('ok.json',JSON.stringify({source:'abcdef',edits:
      [{start:0,end:1,before:'a',after:'LONG'},{start:3,end:5,before:'de',after:'X'}],extra:'ignored'}));
    const r=await run([file]);
    assert.equal(r.code,0);
    assert.equal(r.stdout,'{"text":"LONGbcXf","applied":2}\n');
    assert.equal(r.stderr,'');
  }
  // Empty transaction via CLI.
  {
    const file=write('empty.json',JSON.stringify({source:'x\r\n',edits:[]}));
    const r=await run([file]);
    assert.equal(r.code,0);
    assert.equal(JSON.parse(r.stdout),{text:'x\r\n',applied:0});
    assert.equal(r.stderr,'');
  }
  // Exactly one argument is required.
  for(const args of [[],[ 'a.json','b.json']]){
    const r=await run(args);
    assert.equal(r.code,2);
    assert.ok(r.stderr.length>0);
    assert.equal(r.stdout,'');
  }
  // Unreadable file.
  {
    const missing=path.join(dir,'missing.json');
    assert.equal(existsSync(missing),false);
    const r=await run([missing]);
    assert.equal(r.code,2);
    assert.ok(r.stderr.length>0);
    assert.equal(r.stdout,'');
  }
  // Invalid JSON.
  {
    const file=write('bad.json','{"source":"abc","edits":');
    const r=await run([file]);
    assert.equal(r.code,2);
    assert.ok(r.stderr.length>0);
    assert.equal(r.stdout,'');
  }
  // Non-object top-level JSON.
  {
    const file=write('notobj.json','"abc"');
    const r=await run([file]);
    assert.equal(r.code,2);
    assert.ok(r.stderr.length>0);
    assert.equal(r.stdout,'');
  }
  // Invalid transaction payloads.
  for(const payload of [
    {source:123,edits:[]},
    {source:'abc'},
    {source:'abc',edits:null},
    {source:'abc',edits:[{start:0,end:1,before:'wrong',after:'x'}]},
    {source:'abc',edits:[{start:0,end:2,before:'ab',after:'X'},{start:1,end:2,before:'b',after:'Y'}]},
    {source:'abc',edits:[{start:1,end:1,before:'',after:'X'},{start:1,end:1,before:'',after:'Y'}]}
  ]){
    const file=write('invalid.json',JSON.stringify(payload));
    const r=await run([file]);
    assert.equal(r.code,2);
    assert.ok(r.stderr.length>0);
    assert.equal(r.stdout,'');
    unlinkSync(file);
  }
});

