// Scratch verification: fuzz applyTransaction against an independent reference.
import {applyTransaction,applyEdit} from '/workspace/patch-transaction.js';
import {execFileSync,spawnSync} from 'node:child_process';
import {mkdtempSync,rmSync,writeFileSync} from 'node:fs';
import {tmpdir} from 'node:os';
import path from 'node:path';
import assert from 'node:assert/strict';

const rand=(n)=>Math.floor(Math.random()*n);
const randStr=(n,alphabet)=>{let s='';for(let i=0;i<n;i++)s+=alphabet[rand(alphabet.length)];return s;};
const ALPHABET=['a','b','c','d','\r','\n',' ','\t','é','😀'.codePointAt(0)===0x1f600?'\ud83d\ude00':'x','\u0000'];
function hasConflict(edits){
  for(let i=0;i<edits.length;i++)for(let j=i+1;j<edits.length;j++){
    const a=edits[i],b=edits[j];
    const ai=a.start===a.end,bi=b.start===b.end;
    if(ai&&bi){if(a.start===b.start)return true;}
    else if(ai){if(b.start<=a.start&&a.start<=b.end)return true;}
    else if(bi){if(a.start<=b.start&&b.start<=a.end)return true;}
    else if(a.start<b.end&&b.start<a.end)return true;
  }
  return false;
}
// Independent reference: per-original-index assembly.
function reference(source,edits){
  const covered=new Array(source.length).fill(null);
  const inserts=new Map();
  for(const e of edits){
    if(e.start===e.end){
      if(inserts.has(e.start))throw Error('bad fixture');
